const ASSETS = {"/":{"body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Anton Sheludko — Student &amp; Developer</title>\n    <meta name=\"description\" content=\"Anton Sheludko: final-year school student in Saint Petersburg, Python and C++ programmer, hockey player, and creator of the English-learning platform Eaglish.\">\n    <meta name=\"theme-color\" content=\"#fafaf8\">\n    <meta property=\"og:type\" content=\"website\">\n    <meta property=\"og:title\" content=\"Anton Sheludko — Student &amp; Developer\">\n    <meta property=\"og:description\" content=\"Code, hockey, and learning. A personal portfolio featuring Eaglish, my English-learning project.\">\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n    <link rel=\"stylesheet\" href=\"/styles.css\">\n    <script src=\"/script.js\" defer></script>\n  </head>\n  <body id=\"top\">\n    <a class=\"skip-link\" href=\"#main\">Skip to content</a>\n    <header class=\"site-header\">\n      <div class=\"container header-inner\">\n        <a class=\"wordmark\" href=\"#top\" aria-label=\"Anton, back to top\">Anton<span class=\"wordmark-dot\" aria-hidden=\"true\">.</span></a>\n        <button class=\"menu-toggle\" type=\"button\" aria-expanded=\"false\" aria-controls=\"site-nav\" hidden>\n          <span>Menu</span>\n          <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\"><path d=\"M4 8h16M4 16h16\"/></svg>\n        </button>\n        <nav class=\"site-nav\" id=\"site-nav\" aria-label=\"Main navigation\">\n          <a href=\"#about\">About</a><a href=\"#projects\">Projects</a><a href=\"#achievements\">Achievements</a><a href=\"#experience\">Experience</a><a href=\"#contact\">Contact <span aria-hidden=\"true\">↗</span></a>\n        </nav>\n      </div>\n    </header>\n\n    <main id=\"main\" class=\"container\" tabindex=\"-1\">\n      <section class=\"hero\" aria-labelledby=\"hero-title\">\n        <p class=\"eyebrow\"><span class=\"accent-dot\" aria-hidden=\"true\"></span> A student, always learning</p>\n        <h1 id=\"hero-title\">Hi, I’m<br><span>Anton Sheludko</span><span class=\"accent\">.</span></h1>\n        <p class=\"hero-subtitle\">High school student · Programmer · Hockey player</p>\n        <p class=\"hero-intro\">I’m a final-year school student in Saint Petersburg. I work with Python and C++, and I built Eaglish to make my own English practice more effective.</p>\n        <div class=\"hero-actions\">\n          <a class=\"button\" href=\"#projects\">Explore my project <span aria-hidden=\"true\">↓</span></a>\n          <a class=\"quiet-link\" href=\"https://github.com/AntonShell7\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"GitHub profile (opens in a new tab)\">GitHub <span aria-hidden=\"true\">↗</span></a>\n          <a class=\"quiet-link\" href=\"mailto:antonsheludko37@gmail.com\">Email <span aria-hidden=\"true\">↗</span></a>\n        </div>\n        <p class=\"hero-location\">Saint Petersburg, Russia <span aria-hidden=\"true\">/</span> Class of 2027</p>\n      </section>\n\n      <section class=\"section about-section\" id=\"about\" aria-labelledby=\"about-title\">\n        <div class=\"section-intro\"><p class=\"eyebrow section-number\">01 / About</p><h2 id=\"about-title\">A little about me.</h2></div>\n        <div class=\"about-copy\">\n          <p>I’m in Grade 11 at <strong>Lyceum No. 179 of Saint Petersburg</strong>, with graduation expected in June 2027. I enjoy competitive programming, olympiad mathematics, and chess.</p>\n          <p>Right now, I’m developing my Python and C++ skills, studying mathematics in English, and working on my English at around B2+ level.</p>\n          <p>At 17, I moved to Saint Petersburg for better opportunities in education and hockey. I’ve been living independently since then, balancing school, programming, and training.</p>\n          <p class=\"small-label interests-label\">Code &amp; interests</p>\n          <ul class=\"interest-list\" aria-label=\"Skills and interests\"><li>Python</li><li>C++</li><li>Competitive programming</li><li>Olympiad mathematics</li><li>Language learning</li></ul>\n        </div>\n      </section>\n\n      <section class=\"section projects-section\" id=\"projects\" aria-labelledby=\"projects-title\">\n        <div class=\"section-heading\">\n          <div><p class=\"eyebrow section-number\">02 / Project</p><h2 id=\"projects-title\">Built from a real problem.</h2></div>\n          <p class=\"section-description\">A school project that became<br class=\"desktop-break\"> part of my everyday learning.</p>\n        </div>\n        <article class=\"project-card featured-project\">\n          <div class=\"project-topline\"><span class=\"project-index\">01 / PERSONAL PROJECT</span><span class=\"status\">Live &amp; in use</span></div>\n          <div class=\"project-story-heading\"><h3>Eaglish<span class=\"accent\">.</span></h3><p>An English-learning platform</p></div>\n          <p class=\"project-summary\">I was spending time on English without making the progress I wanted. That question became my school project: how could I build a better way to learn?</p>\n          <div class=\"project-story-grid\">\n            <div><h4>The idea</h4><p>I began researching memory and long-term learning. Over six months, I turned that research into a working platform built around vocabulary in context and spaced repetition.</p></div>\n            <div><h4>What I built</h4><p>I took Eaglish from the initial idea to the working application. It brings together reading, vocabulary practice, and writing. My friends and I now use it regularly.</p></div>\n            <div><h4>What changed for me</h4><p>Building Eaglish changed how I approach learning languages. Over the same six months, my self-assessed English level improved from A2 to B2.</p></div>\n          </div>\n          <div class=\"project-tech-row\"><span class=\"small-label\">Built with</span><ul class=\"interest-list\" aria-label=\"Eaglish technologies\"><li>React</li><li>TypeScript</li><li>Vite</li><li>Tailwind CSS</li><li>Supabase</li></ul></div>\n          <div class=\"project-links real-project-links\">\n            <a href=\"https://eaglish.ru/\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Visit Eaglish (opens in a new tab)\">Visit Eaglish <span aria-hidden=\"true\">↗</span></a>\n            <a href=\"https://github.com/AntonShell7/eaglish\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Eaglish source on GitHub (opens in a new tab)\">View on GitHub <span aria-hidden=\"true\">↗</span></a>\n          </div>\n        </article>\n      </section>\n\n      <section class=\"section achievements-section\" id=\"achievements\" aria-labelledby=\"achievements-title\">\n        <div class=\"section-intro\"><p class=\"eyebrow section-number\">03 / Achievements</p><h2 id=\"achievements-title\">Milestones<br> along the way.</h2></div>\n        <div id=\"achievements-content\"><!-- ACHIEVEMENTS_START --><p class=\"empty-note\">Achievements and certificates will be added here.</p><!-- ACHIEVEMENTS_END --></div>\n      </section>\n\n      <section class=\"section experience-section\" id=\"experience\" aria-labelledby=\"experience-title\">\n        <div class=\"section-heading\"><div><p class=\"eyebrow section-number\">04 / Education &amp; experience</p><h2 id=\"experience-title\">In class. On the ice.</h2></div><p class=\"section-description\">Two important parts<br class=\"desktop-break\"> of my everyday life.</p></div>\n        <div class=\"experience-grid\">\n          <article class=\"experience-entry\"><p class=\"small-label\">Education</p><h3>Lyceum No. 179 of Saint Petersburg</h3><p class=\"experience-meta\">Grade 11 · Expected graduation: June 2027</p><p>I’m in my final year of secondary school, preparing for Russia’s Unified State Exam (EGE) in mathematics and computer science.</p></article>\n          <article class=\"experience-entry\"><p class=\"small-label\">Hockey</p><h3>Kronverkskie Barsy</h3><p class=\"experience-meta\">ITMO University hockey team · Saint Petersburg</p><p>I’ve played hockey for 14 years and train and compete at a professional level. Alongside school, I play for ITMO University’s Kronverkskie Barsy team.</p></article>\n        </div>\n      </section>\n\n      <section class=\"contact-section\" id=\"contact\" aria-labelledby=\"contact-title\">\n        <p class=\"eyebrow section-number\">05 / Contact</p><h2 id=\"contact-title\">Let’s get in touch.</h2><p>I’m happy to talk about projects, learning,<br class=\"desktop-break\"> or an interesting idea.</p>\n        <div class=\"contact-links\"><a class=\"contact-email\" href=\"mailto:antonsheludko37@gmail.com\">antonsheludko37@gmail.com <span aria-hidden=\"true\">↗</span></a><div class=\"contact-socials\"><a href=\"https://github.com/AntonShell7\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"GitHub profile (opens in a new tab)\">GitHub <span aria-hidden=\"true\">↗</span></a></div></div>\n      </section>\n    </main>\n    <footer class=\"site-footer container\"><p>© <span id=\"current-year\">2026</span> Anton Sheludko</p><div class=\"footer-links\"><a id=\"admin-link\" href=\"/admin\" hidden>Manage achievements</a><a href=\"#top\">Back to top <span aria-hidden=\"true\">↑</span></a></div></footer>\n  </body>\n</html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":"/* Change these values to personalize the entire site. No build step needed. */\n:root {\n  color-scheme: light;\n  --background: #fafaf8;\n  --surface: #ffffff;\n  --text: #222729;\n  --muted: #636b72;\n  --accent: #2857b5;\n  --accent-soft: #edf2fc;\n  --border: #e0e3e3;\n  --font: -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n  --mono: ui-monospace, \"SFMono-Regular\", Consolas, monospace;\n}\n\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; scroll-padding-top: 100px; }\nbody { margin: 0; background: var(--background); color: var(--text); font-family: var(--font); font-size: 16px; line-height: 1.65; -webkit-font-smoothing: antialiased; }\n[hidden] { display: none !important; }\n::selection { color: var(--text); background: #dbe6fd; }\na { color: inherit; text-decoration: none; }\na[href], button { -webkit-tap-highlight-color: transparent; }\nbutton { font: inherit; }\nbutton, a[href] { touch-action: manipulation; }\na[href]:focus-visible, button:focus-visible { outline: 3px solid var(--accent); outline-offset: 5px; border-radius: 3px; }\nh1, h2, h3, p { margin: 0; }\nh1, h2, h3 { font-weight: 600; }\n.container { width: min(1000px, calc(100% - 64px)); margin-inline: auto; }\n.accent { color: var(--accent); }\nstrong { color: var(--text); font-weight: 550; }\n.hero-location { margin-top: 27px; color: var(--muted); font-family: var(--mono); font-size: 10px; }\n.hero-location span { padding-inline: 9px; color: #9ba4ae; }\n.quiet-link[href]:hover, .contact-socials a:hover, .contact-email:hover { color: var(--accent); }\n.featured-project { margin-top: 30px; padding: 30px 32px 20px; }\n.project-story-heading { display: flex; align-items: baseline; flex-wrap: wrap; gap: 11px 20px; }\n.project-story-heading h3 { font-size: 36px; }\n.project-story-heading > p { font-size: 13px; }\n.featured-project .project-summary { max-width: 650px; margin-top: 6px; font-size: 16px; line-height: 1.8; }\n.project-story-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 28px; margin-top: 27px; }\n.project-story-grid h4 { margin: 0 0 9px; font-size: 13px; font-weight: 600; }\n.project-story-grid p { font-size: 13px; line-height: 1.9; }\n.project-tech-row { margin-top: 28px; }\n.real-project-links a { min-height: 44px; color: var(--accent); font-size: 12px; gap: 9px; }\n.real-project-links a:hover { text-decoration: underline; text-underline-offset: 4px; }\n.empty-note { padding: 12px 0; color: var(--muted); font-size: 14px; }\n.achievement-description { white-space: pre-line; }\n.achievement-file { display: inline-flex; gap: 7px; align-items: center; min-height: 44px; margin-top: 6px; color: var(--accent); font-size: 12px; }\n.achievement-file:hover { text-decoration: underline; }\n.achievement-files { display: flex; flex-wrap: wrap; gap: 15px; }\n.footer-links { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px 22px; }\n.footer-links a { display: inline-flex; gap: 8px; align-items: center; min-height: 44px; }\n.footer-links a:hover { color: var(--accent); }\n.skip-link { position: fixed; z-index: 10; top: 12px; left: 12px; padding: 10px 18px; color: white; background: var(--accent); transform: translateY(-160%); }\n.skip-link:focus { transform: translateY(0); }\n#main:focus { outline: none; }\n\n/* Compact navigation. Without JavaScript, the links stay visible on mobile. */\n.site-header { position: sticky; z-index: 5; top: 0; background: var(--background); border-bottom: 1px solid var(--border); }\n.header-inner { display: flex; align-items: center; justify-content: space-between; gap: 24px; min-height: 80px; }\n.wordmark { flex-shrink: 0; font-size: 17px; font-weight: 650; letter-spacing: -.035em; }\n.wordmark-dot { color: var(--accent); }\n.site-nav { display: flex; align-items: center; gap: 28px; }\n.site-nav a { display: inline-flex; align-items: center; gap: 7px; min-height: 44px; color: var(--muted); font-size: 13px; transition: color .15s ease; }\n.site-nav a:hover, .site-nav a[aria-current=\"location\"] { color: var(--accent); }\n.menu-toggle { display: none; }\n\n/* A typographic introduction keeps the focus on the student. */\n.hero { padding: 91px 0 88px; }\n.eyebrow { display: flex; align-items: center; gap: 9px; color: var(--accent); font-family: var(--mono); font-size: 10px; font-weight: 500; line-height: 1.5; letter-spacing: .12em; text-transform: uppercase; }\n.accent-dot { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }\nh1 { margin-top: 27px; font-size: clamp(46px, 6.5vw, 76px); line-height: 1.09; letter-spacing: -.065em; font-weight: 600; }\n.hero-subtitle { margin-top: 26px; font-size: 17px; font-weight: 500; letter-spacing: -.015em; }\n.hero-intro { max-width: 540px; margin-top: 14px; color: var(--muted); font-size: 17px; line-height: 1.8; }\n.hero-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 25px; margin-top: 31px; }\n.button { display: inline-flex; justify-content: center; align-items: center; gap: 23px; min-height: 46px; padding: 10px 19px; background: var(--accent); color: white; border: 1px solid var(--accent); border-radius: 6px; font-size: 13px; font-weight: 500; transition: background .15s ease, border-color .15s ease; }\n.button:hover { background: #204795; border-color: #204795; }\n.button span { font-size: 17px; }\n.quiet-link { display: inline-flex; align-items: center; flex-wrap: wrap; gap: 7px; min-height: 44px; font-size: 13px; }\n.optional-link { overflow-wrap: anywhere; }\n.optional-link:not([href]) { color: var(--muted); cursor: default; }\n.link-state { color: var(--muted); font-size: 10px; font-weight: 400; }\n.optional-link[href] { color: var(--accent); }\n.optional-link[href]:hover { text-decoration: underline; text-underline-offset: 4px; }\n.optional-link[href] .link-state { color: inherit; }\n\n/* Numbered sections, consistent spacing, and a simple two-column rhythm. */\n.section { padding: 65px 0; border-top: 1px solid var(--border); }\n.section-number { color: var(--muted); font-size: 10px; }\nh2 { margin-top: 17px; font-size: 32px; line-height: 1.2; letter-spacing: -.045em; }\n.about-section, .achievements-section { display: grid; grid-template-columns: 1fr 1.65fr; gap: 58px; }\n.about-copy { padding-top: 2px; }\n.about-copy > p { color: var(--muted); font-size: 15px; line-height: 1.85; }\n.about-copy > p + p { margin-top: 15px; }\n.placeholder { color: var(--text); }\n.small-label { display: block; color: var(--muted); font-family: var(--mono); font-size: 9px; line-height: 1.6; letter-spacing: .07em; text-transform: uppercase; }\n.about-copy > .interests-label { margin-top: 26px; font-size: 9px; }\n.interest-list { display: flex; flex-wrap: wrap; gap: 8px; margin: 11px 0 0; padding: 0; list-style: none; }\n.interest-list li { padding: 4px 10px; border: 1px solid var(--border); border-radius: 5px; color: #525c67; font-size: 11px; line-height: 1.7; }\n.section-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 35px; }\n.section-description { color: var(--muted); font-size: 13px; line-height: 1.75; }\n.section-intro .section-description { margin-top: 18px; }\n\n/* Project cards: text first, with honest statuses and no stock imagery. */\n.example-note { display: flex; align-items: flex-start; gap: 9px; margin: 25px 0 19px; color: var(--muted); font-size: 11px; line-height: 1.7; }\n.note-dot { flex-shrink: 0; width: 5px; height: 5px; margin-top: 7px; border-radius: 50%; background: #7d8a9b; }\n.project-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }\n.project-card { display: flex; flex-direction: column; padding: 27px 29px 20px; border: 1px solid var(--border); border-radius: 10px; background: var(--surface); }\n.project-topline { display: flex; align-items: center; justify-content: space-between; gap: 15px; margin-bottom: 25px; }\n.project-index { color: #7a8189; font-family: var(--mono); font-size: 11px; }\n.status { padding: 3px 8px; background: var(--accent-soft); border: 1px solid #e0e8f9; border-radius: 4px; color: #476494; font-size: 9px; line-height: 1.6; }\nh3 { font-size: 20px; line-height: 1.35; letter-spacing: -.03em; overflow-wrap: anywhere; }\n.project-card h3 { margin-bottom: 11px; }\n.project-card p { max-width: 420px; color: var(--muted); font-size: 13px; line-height: 1.8; }\n.project-technologies { display: flex; flex-direction: column; align-items: flex-start; gap: 9px; margin-top: auto; padding-top: 25px; }\n.technology-placeholder { color: #59636d; font-family: var(--mono); font-size: 10px; }\n.project-links { display: flex; align-items: center; flex-wrap: wrap; gap: 23px; margin-top: 22px; padding-top: 12px; border-top: 1px solid #eceeee; }\n.project-links a { display: inline-flex; align-items: center; flex-wrap: wrap; gap: 7px; min-height: 32px; font-size: 11px; }\n.project-links .link-state { font-size: 9px; }\n.project-card-wide { grid-column: 1 / -1; }\n.project-card-wide .project-topline { margin-bottom: 18px; }\n.wide-project-content { display: grid; grid-template-columns: 1.3fr 1fr; align-items: start; gap: 65px; }\n.wide-project-details .project-technologies { padding-top: 3px; }\n.wide-project-details .project-links { margin-top: 15px; }\n\n/* Verified milestones and education can be added without changing layout. */\n.milestone-list { margin: 0; padding: 0; list-style: none; }\n.milestone-list li { display: grid; grid-template-columns: 50px 1fr; gap: 23px; padding: 0 0 26px; }\n.milestone-list li + li { padding-top: 26px; border-top: 1px solid var(--border); }\n.milestone-list li:last-child { padding-bottom: 0; }\n.timeline-year { padding-top: 3px; color: var(--muted); font-family: var(--mono); font-size: 10px; }\n.milestone-list h3 { font-size: 16px; }\n.milestone-list p { margin-top: 9px; color: var(--muted); font-size: 12px; line-height: 1.8; }\n.entry-note { display: block; margin-top: 12px; color: #687384; font-size: 10px; }\n.experience-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 55px; margin-top: 33px; }\n.experience-entry { padding-left: 19px; border-left: 2px solid #d9e1ef; }\n.experience-entry h3 { margin-top: 13px; font-size: 19px; }\n.experience-entry .experience-meta { margin-top: 8px; font-size: 11px; }\n.experience-entry > p:last-child { margin-top: 17px; color: var(--muted); font-size: 13px; line-height: 1.8; }\n.experience-meta { color: var(--muted); }\n\n/* A restrained closing section. Real contact links activate when supplied. */\n.contact-section { padding: 44px 42px 38px; margin: 5px 0 53px; border: 1px solid #e2e7f0; border-radius: 12px; background: #f0f3f9; }\n.contact-section .section-number { color: #5a6f91; }\n.contact-section h2 { margin-top: 15px; font-size: 38px; }\n.contact-section > p:not(.eyebrow) { margin-top: 14px; color: var(--muted); font-size: 14px; line-height: 1.8; }\n.contact-links { display: flex; align-items: center; justify-content: space-between; gap: 28px; margin-top: 30px; padding-top: 24px; border-top: 1px solid #d9e1ec; }\n.contact-email { display: inline-flex; align-items: center; flex-wrap: wrap; gap: 12px; min-height: 44px; font-size: 21px; font-weight: 500; letter-spacing: -.03em; }\n.contact-email:not([href]) { color: #4b5a73; }\n.contact-socials { display: flex; flex-wrap: wrap; gap: 20px; }\n.contact-socials a { display: inline-flex; align-items: center; flex-wrap: wrap; gap: 8px; min-height: 44px; font-size: 12px; }\n.contact-socials .link-state { font-size: 9px; }\n.site-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding-bottom: 30px; color: var(--muted); font-size: 10px; }\n.site-footer .draft-note { margin-top: 5px; font-size: 9px; }\n.site-footer > a { display: inline-flex; align-items: center; gap: 12px; min-height: 44px; flex-shrink: 0; }\n.site-footer > a:hover { color: var(--accent); }\n\n@media (min-width: 1600px) {\n  .hero { padding-top: 105px; }\n}\n\n@media (max-width: 800px) {\n  .project-story-grid { grid-template-columns: 1fr; gap: 21px; }\n  .project-story-grid p { max-width: none; }\n  .site-nav { gap: 17px; }\n  .site-nav a { font-size: 12px; }\n  .header-inner { min-height: 72px; }\n  .hero { padding-top: 72px; padding-bottom: 72px; }\n  .about-section, .achievements-section { grid-template-columns: 1fr 1.5fr; gap: 30px; }\n  .section { padding: 53px 0; }\n  .project-card { padding: 24px 22px 17px; }\n  .wide-project-content { gap: 32px; }\n  .project-links { gap: 15px; }\n  .experience-grid { gap: 30px; }\n}\n\n@media (max-width: 640px) {\n  .featured-project { padding: 23px 23px 17px; }\n  .project-story-heading { gap: 0; flex-direction: column; }\n  .project-story-heading h3 { font-size: 32px !important; }\n  .featured-project .project-summary { font-size: 14px; margin-top: 19px; }\n  .contact-links .contact-email { font-size: 16px; overflow-wrap: anywhere; }\n  .hero-location { font-size: 9px; line-height: 1.9; }\n  .footer-links { column-gap: 15px; }\n  html { scroll-padding-top: 92px; }\n  .container { width: calc(100% - 40px); }\n  .header-inner { flex-wrap: wrap; gap: 0; min-height: 66px; }\n  .wordmark { display: flex; align-items: center; min-height: 66px; font-size: 16px; }\n  .site-nav { width: 100%; flex-wrap: wrap; gap: 0 21px; padding: 0 0 12px; }\n  .site-nav a { min-height: 42px; font-size: 13px; }\n  .js .menu-toggle { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 2px 0 12px; border: 0; color: var(--text); background: transparent; font-size: 12px; cursor: pointer; }\n  .js .site-nav:not(.is-open) { display: none; }\n  .js .site-nav.is-open { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); padding: 5px 0 15px; }\n  .hero { padding: 57px 0 53px; }\n  .eyebrow { font-size: 9px; }\n  h1 { margin-top: 24px; font-size: clamp(34px, 8.5vw, 52px); line-height: 1.12; letter-spacing: -.055em; }\n  .hero-subtitle { max-width: 330px; margin-top: 23px; font-size: 14px; line-height: 1.7; }\n  .hero-intro { margin-top: 12px; font-size: 15px; line-height: 1.85; }\n  .hero-actions { display: grid; grid-template-columns: repeat(3, max-content); gap: 9px 23px; margin-top: 26px; }\n  .hero-actions .button { grid-column: 1 / -1; justify-self: start; }\n  .button { min-height: 45px; font-size: 12px; padding-inline: 15px; gap: 16px; }\n  .quiet-link { gap: 5px; font-size: 11px; }\n  .quiet-link .link-state { font-size: 9px; }\n  .section { padding: 43px 0; }\n  h2 { margin-top: 13px; font-size: 29px; }\n  .about-section, .achievements-section { grid-template-columns: 1fr; gap: 25px; }\n  .about-copy > p { font-size: 14px; }\n  .interest-list { gap: 7px; }\n  .interest-list li { font-size: 10px; }\n  .section-heading { flex-direction: column; align-items: flex-start; gap: 15px; }\n  .section-description { font-size: 13px; }\n  .desktop-break { display: none; }\n  .example-note { margin: 20px 0 17px; font-size: 10px; }\n  .project-grid { grid-template-columns: 1fr; gap: 14px; }\n  .project-card { padding: 22px 23px 18px; }\n  .project-topline { margin-bottom: 22px; }\n  .project-card h3 { font-size: 20px; }\n  .project-card p { font-size: 13px; }\n  .project-technologies { padding-top: 23px; }\n  .project-links { gap: 24px; }\n  .project-links a { min-height: 44px; }\n  .project-card-wide { grid-column: auto; }\n  .wide-project-content { grid-template-columns: 1fr; gap: 0; }\n  .wide-project-details .project-technologies { padding-top: 23px; }\n  .wide-project-details .project-links { margin-top: 22px; }\n  .achievements-section h2 br { display: none; }\n  .section-intro .section-description { margin-top: 13px; }\n  .milestone-list { margin-top: 4px; }\n  .milestone-list li { grid-template-columns: 42px 1fr; gap: 17px; }\n  .milestone-list h3 { font-size: 15px; }\n  .experience-grid { grid-template-columns: 1fr; gap: 30px; margin-top: 28px; }\n  .experience-entry { padding-left: 17px; }\n  .contact-section { margin: 3px 0 30px; padding: 29px 24px 25px; }\n  .contact-section h2 { font-size: 31px; }\n  .contact-section > p:not(.eyebrow) { font-size: 13px; }\n  .contact-links { flex-direction: column; align-items: flex-start; gap: 7px; margin-top: 24px; padding-top: 19px; }\n  .contact-email { font-size: 20px; }\n  .site-footer { align-items: flex-start; padding-bottom: 23px; font-size: 9px; }\n  .site-footer .draft-note { max-width: 190px; font-size: 8px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  html { scroll-behavior: auto; }\n  *, *::before, *::after { transition: none !important; animation: none !important; }\n}\n","type":"text/css; charset=utf-8"},"/script.js":{"body":"// The portfolio content is in index.html. These are small navigation enhancements.\ndocument.documentElement.classList.add(\"js\");\nconst menuButton = document.querySelector(\".menu-toggle\");\nconst navigation = document.querySelector(\"#site-nav\");\nmenuButton.hidden = false;\nfunction closeMenu() {\n  menuButton.setAttribute(\"aria-expanded\", \"false\");\n  navigation.classList.remove(\"is-open\");\n}\nmenuButton.addEventListener(\"click\", () => {\n  const open = menuButton.getAttribute(\"aria-expanded\") !== \"true\";\n  menuButton.setAttribute(\"aria-expanded\", String(open));\n  navigation.classList.toggle(\"is-open\", open);\n});\nnavigation.addEventListener(\"click\", (event) => { if (event.target.closest(\"a\")) closeMenu(); });\ndocument.addEventListener(\"keydown\", (event) => {\n  if (event.key === \"Escape\" && menuButton.getAttribute(\"aria-expanded\") === \"true\") { closeMenu(); menuButton.focus(); }\n});\nwindow.matchMedia(\"(min-width: 641px)\").addEventListener(\"change\", closeMenu);\nconst sections = document.querySelectorAll(\"main section[id]\");\nlet currentSection = \"\";\nfunction updateActiveSection() {\n  let active = \"\";\n  sections.forEach(section => { if (section.getBoundingClientRect().top <= 140) active = section.id; });\n  if (window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - 2) active = \"contact\";\n  if (active === currentSection) return;\n  currentSection = active;\n  navigation.querySelectorAll(\"a\").forEach(link => {\n    if (link.hash === \"#\" + active) link.setAttribute(\"aria-current\", \"location\");\n    else link.removeAttribute(\"aria-current\");\n  });\n}\nwindow.addEventListener(\"scroll\", updateActiveSection, { passive: true });\nwindow.addEventListener(\"resize\", updateActiveSection);\nupdateActiveSection();\ndocument.querySelector(\"#current-year\").textContent = new Date().getFullYear();\n\n// Visibility is a convenience. The server separately authorizes every admin request.\nfetch(\"/api/session\", { credentials: \"same-origin\" })\n  .then(response => response.ok ? response.json() : null)\n  .then(session => { if (session?.isAdmin) document.querySelector(\"#admin-link\").hidden = false; })\n  .catch(() => {});\n","type":"text/javascript; charset=utf-8"},"/favicon.svg":{"body":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\">\n  <rect width=\"64\" height=\"64\" rx=\"14\" fill=\"#edf2fc\"/>\n  <path d=\"m24 20-12 12 12 12m16-24 12 12-12 12\" fill=\"none\" stroke=\"#2857b5\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n</svg>\n","type":"image/svg+xml"},"/admin":{"body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <meta name=\"robots\" content=\"noindex, nofollow\"><title>Achievements — Anton’s Admin</title>\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/styles.css\"><link rel=\"stylesheet\" href=\"/admin.css\">\n    <script src=\"/admin.js\" defer></script>\n  </head>\n  <body>\n    <a class=\"skip-link\" href=\"#admin-main\">Skip to content</a>\n    <header class=\"site-header\"><div class=\"container header-inner\"><a class=\"wordmark\" href=\"/\">Anton<span class=\"wordmark-dot\">.</span> <span class=\"admin-wordmark\">/ admin</span></a><a class=\"quiet-link\" href=\"/\">View portfolio <span aria-hidden=\"true\">↗</span></a></div></header>\n    <main class=\"container admin-main\" id=\"admin-main\" tabindex=\"-1\">\n      <div class=\"admin-heading\"><p class=\"eyebrow\">Your portfolio, your story</p><h1>Your achievements.</h1><p>Add awards, competitions, and certificates. Keep a draft or publish it when you’re ready.</p></div>\n      <p id=\"local-notice\" class=\"admin-notice\" hidden>Local preview — these records stay on this computer and are separate from your published portfolio.</p>\n      <p id=\"page-status\" class=\"page-status\" role=\"status\" aria-live=\"polite\"></p>\n      <div class=\"admin-layout\">\n        <section class=\"editor-card\" aria-labelledby=\"editor-title\">\n          <div class=\"editor-heading\"><h2 id=\"editor-title\">Add an achievement</h2><button id=\"cancel-edit\" class=\"text-button\" type=\"button\" hidden>Cancel editing</button></div>\n          <form id=\"achievement-form\">\n            <input type=\"hidden\" name=\"id\"><input type=\"hidden\" name=\"updatedAt\">\n            <div class=\"form-field\"><label for=\"achievement-title\">Achievement name <span class=\"required\">*</span></label><input id=\"achievement-title\" name=\"title\" maxlength=\"160\" required placeholder=\"The name of your award or certificate\"></div>\n            <div class=\"form-row\">\n              <div class=\"form-field\"><label for=\"achievement-year\">Year received <span class=\"required\">*</span></label><input id=\"achievement-year\" name=\"year\" type=\"number\" min=\"1900\" max=\"2100\" step=\"1\" required placeholder=\"2026\"></div>\n              <div class=\"form-field\"><label for=\"achievement-category\">Category <span class=\"required\">*</span></label><select id=\"achievement-category\" name=\"category\" required><option>Award</option><option>Olympiad</option><option>Competition</option><option>Certificate</option><option>Other</option></select></div>\n            </div>\n            <div class=\"form-field\"><label for=\"achievement-organizer\">Organizer <span class=\"optional\">optional</span></label><input id=\"achievement-organizer\" name=\"organizer\" maxlength=\"160\" placeholder=\"School, competition, or issuing organization\"></div>\n            <div class=\"form-field\"><label for=\"achievement-description\">A short description <span class=\"optional\">optional</span></label><textarea id=\"achievement-description\" name=\"description\" rows=\"4\" maxlength=\"1500\" placeholder=\"Your result, what you did, or why it matters to you.\"></textarea><span class=\"field-hint\">Write this in English, as you’d like it to appear on your portfolio.</span></div>\n            <div class=\"form-field\"><label for=\"achievement-proof\">Source link <span class=\"optional\">optional</span></label><input id=\"achievement-proof\" name=\"proofUrl\" type=\"url\" maxlength=\"1500\" placeholder=\"https://...\"><span class=\"field-hint\">An official results page or an online certificate.</span></div>\n            <div class=\"form-field\"><label for=\"achievement-file\">Certificate or photo <span class=\"optional\">optional</span></label><input id=\"achievement-file\" name=\"file\" type=\"file\" accept=\"application/pdf,image/jpeg,image/png,image/webp\" aria-describedby=\"file-hint\"><span id=\"file-hint\" class=\"field-hint\">PDF, JPG, PNG, or WebP · up to 10 MB</span><p id=\"selected-file\" class=\"selected-file\" aria-live=\"polite\"></p>\n              <div id=\"existing-file\" class=\"existing-file\" hidden><a id=\"existing-file-link\" target=\"_blank\" rel=\"noopener noreferrer\">Open current attachment ↗</a><label class=\"checkbox-label\"><input type=\"checkbox\" name=\"removeFile\">Remove the current attachment</label></div>\n            </div>\n            <div class=\"publish-setting\"><label class=\"checkbox-label\"><input type=\"checkbox\" name=\"published\">Publish on my portfolio</label><p>Unchecked achievements are private drafts. Published attachments can be opened by portfolio visitors.</p></div>\n            <p id=\"form-status\" class=\"form-status\" role=\"status\" aria-live=\"polite\"></p>\n            <button id=\"save-button\" type=\"submit\" class=\"button\">Save achievement <span aria-hidden=\"true\">↗</span></button>\n          </form>\n        </section>\n        <section class=\"collection\" aria-labelledby=\"collection-title\"><div class=\"collection-heading\"><h2 id=\"collection-title\">Your collection</h2><span id=\"achievement-count\" class=\"collection-count\">0</span></div><div id=\"achievement-list\"><p class=\"collection-empty\">Loading achievements…</p></div></section>\n      </div>\n    </main>\n    <footer class=\"site-footer container\"><p>Anton Sheludko · Portfolio admin</p><a href=\"/\">Back to portfolio <span aria-hidden=\"true\">↗</span></a></footer>\n    <dialog id=\"delete-dialog\" aria-labelledby=\"delete-title\"><form method=\"dialog\"><h2 id=\"delete-title\">Delete this achievement?</h2><p id=\"delete-description\"></p><p>Its attachment will also be removed.</p><div class=\"dialog-actions\"><button class=\"secondary-button\" value=\"cancel\" autofocus>Keep it</button><button id=\"confirm-delete\" class=\"danger-button\" type=\"button\">Delete achievement</button></div><p id=\"delete-status\" role=\"status\" aria-live=\"polite\"></p></form></dialog>\n  </body>\n</html>\n","type":"text/html; charset=utf-8"},"/admin.css":{"body":".admin-wordmark { margin-left: 6px; color: var(--muted); font-size: 12px; font-weight: 400; letter-spacing: 0; }\n.admin-main { padding-top: 55px; padding-bottom: 70px; }\n.admin-heading h1 { font-size: 44px; margin-top: 16px; letter-spacing: -.045em; }\n.admin-heading > p:last-child { margin-top: 15px; max-width: 620px; font-size: 15px; color: var(--muted); }\n.admin-notice { padding: 13px 17px; margin-top: 24px; border: 1px solid #d9e2f2; background: var(--accent-soft); color: #435d86; border-radius: 6px; font-size: 12px; }\n.page-status { min-height: 20px; margin: 18px 0 14px; color: var(--muted); font-size: 13px; }\n.admin-layout { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, .8fr); gap: 35px; align-items: start; }\n.editor-card { padding: 28px; border: 1px solid var(--border); background: white; border-radius: 10px; }\n.editor-heading, .collection-heading { display: flex; justify-content: space-between; align-items: center; gap: 15px; }\n.editor-heading { margin-bottom: 25px; }\n.admin-main h2 { font-size: 20px; margin: 0; letter-spacing: -.025em; }\n.form-field { display: flex; flex-direction: column; gap: 8px; margin-bottom: 19px; min-width: 0; }\n.form-field > label { font-size: 12px; font-weight: 550; }\n.optional { margin-left: 4px; color: var(--muted); font-weight: 400; font-size: 10px; }\n.required { color: var(--accent); }\ninput:not([type=\"checkbox\"]):not([type=\"hidden\"]), select, textarea { width: 100%; min-height: 44px; padding: 11px 12px; border: 1px solid #dce0e5; border-radius: 5px; background: #fcfcfb; color: var(--text); font: inherit; font-size: 14px; }\ninput::placeholder, textarea::placeholder { color: #7a828c; font-size: 12px; }\ninput:focus-visible, select:focus-visible, textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\ntextarea { resize: vertical; min-height: 110px; line-height: 1.7; }\n.form-row { display: grid; grid-template-columns: .7fr 1fr; gap: 16px; }\n.field-hint { color: var(--muted); font-size: 10px; line-height: 1.7; }\ninput[type=\"file\"] { padding: 11px; font-size: 11px; }\ninput::file-selector-button { margin-right: 10px; border: 1px solid var(--border); padding: 6px 10px; border-radius: 4px; background: white; color: var(--text); cursor: pointer; }\n.selected-file { overflow-wrap: anywhere; font-size: 11px; color: var(--muted); }\n.existing-file { border-top: 1px solid var(--border); padding-top: 12px; font-size: 11px; }\n.existing-file a { color: var(--accent); display: inline-flex; min-height: 35px; align-items: center; overflow-wrap: anywhere; }\n.checkbox-label { display: flex; align-items: flex-start; gap: 9px; font-size: 12px; line-height: 1.7; }\n.checkbox-label input { width: 16px; height: 16px; margin: 3px 0 0; accent-color: var(--accent); flex-shrink: 0; }\n.publish-setting { margin-top: 24px; padding: 17px; border: 1px solid var(--border); border-radius: 6px; background: var(--background); }\n.publish-setting > p { margin: 8px 0 0 25px; color: var(--muted); font-size: 10px; }\n.form-status { min-height: 20px; margin-top: 18px; font-size: 12px; color: var(--muted); }\n.form-status.error, .page-status.error, #delete-status { color: #a23131; }\n#save-button { width: 100%; margin-top: 10px; cursor: pointer; }\nbutton:disabled { cursor: wait; opacity: .6; }\n.text-button { min-height: 44px; padding: 4px 0; background: none; border: 0; font-size: 11px; color: var(--accent); cursor: pointer; }\n.text-button:hover { text-decoration: underline; text-underline-offset: 3px; }\n.collection { padding-top: 8px; }\n.collection-heading { padding-bottom: 20px; border-bottom: 1px solid var(--border); }\n.collection-count { min-width: 25px; padding: 2px 8px; border-radius: 5px; background: #eceff3; color: #606c7e; font-family: var(--mono); font-size: 11px; text-align: center; }\n.collection-empty { padding: 29px 0; color: var(--muted); font-size: 13px; line-height: 1.85; }\n.achievement-item { padding: 22px 0 15px; border-bottom: 1px solid var(--border); }\n.achievement-item h3 { font-size: 16px; }\n.item-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 9px; margin-bottom: 9px; color: var(--muted); font-size: 10px; }\n.item-status { padding: 1px 7px; color: #356442; background: #eaf3ec; border-radius: 3px; }\n.item-status.draft { background: #edf0f4; color: #5e6a7a; }\n.item-description { margin-top: 9px; font-size: 12px; color: var(--muted); line-height: 1.8; white-space: pre-line; overflow-wrap: anywhere; }\n.item-attachment { display: inline-block; max-width: 100%; padding-top: 9px; color: var(--accent); overflow-wrap: anywhere; font-size: 11px; }\n.item-actions { display: flex; gap: 25px; margin-top: 6px; }\n.item-actions .delete-button { color: #8d4545; }\ndialog { max-width: min(430px, calc(100% - 32px)); padding: 27px; border: 1px solid var(--border); border-radius: 12px; color: var(--text); }\ndialog::backdrop { background: #1e273a55; }\ndialog h2 { margin: 0 0 14px; font-size: 23px; }\ndialog p { margin-top: 10px; color: var(--muted); font-size: 13px; overflow-wrap: anywhere; }\n.dialog-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 24px; }\n.secondary-button, .danger-button { min-height: 44px; padding: 10px 14px; border-radius: 5px; font-size: 12px; cursor: pointer; }\n.secondary-button { background: white; border: 1px solid var(--border); }\n.danger-button { background: #9c3636; color: white; border: 1px solid #9c3636; }\n@media(max-width: 800px) { .admin-layout { gap: 23px; } .editor-card { padding: 22px; } }\n@media(max-width: 640px) { .admin-main { padding-top: 38px; } .admin-heading h1 { font-size: 34px; } .admin-heading > p:last-child { font-size: 14px; } .admin-layout { grid-template-columns: 1fr; gap: 38px; } .editor-card { padding: 23px 19px; } .form-row { gap: 12px; } .editor-heading { flex-wrap: wrap; gap: 0; } .admin-notice { font-size: 11px; } }\n","type":"text/css; charset=utf-8"},"/admin.js":{"body":"const form = document.querySelector(\"#achievement-form\");\nconst list = document.querySelector(\"#achievement-list\");\nconst formStatus = document.querySelector(\"#form-status\");\nconst pageStatus = document.querySelector(\"#page-status\");\nconst saveButton = document.querySelector(\"#save-button\");\nconst deleteDialog = document.querySelector(\"#delete-dialog\");\nlet achievements = [];\nlet pendingDelete = null;\n\nfunction field(name) { return form.elements.namedItem(name); }\nfunction status(element, message, error = false) { element.textContent = message; element.classList.toggle(\"error\", error); }\nasync function api(path, options = {}) {\n  const response = await fetch(path, { credentials: \"same-origin\", ...options, headers: { ...(options.method ? { \"X-Portfolio-Request\": \"1\" } : {}), ...options.headers } });\n  const data = await response.json();\n  if (!response.ok) throw new Error(data.error || \"The request could not be completed.\");\n  return data;\n}\nfunction element(tag, className, text) { const node = document.createElement(tag); if (className) node.className = className; if (text !== undefined) node.textContent = text; return node; }\nfunction resetEditor() {\n  form.reset(); field(\"id\").value = \"\"; field(\"updatedAt\").value = \"\";\n  document.querySelector(\"#editor-title\").textContent = \"Add an achievement\";\n  document.querySelector(\"#cancel-edit\").hidden = true;\n  document.querySelector(\"#existing-file\").hidden = true;\n  document.querySelector(\"#selected-file\").textContent = \"\";\n  field(\"file\").setCustomValidity(\"\");\n  status(formStatus, \"\");\n}\nfunction edit(record) {\n  resetEditor();\n  for (const name of [\"id\", \"updatedAt\", \"title\", \"year\", \"category\", \"organizer\", \"description\", \"proofUrl\"]) field(name).value = record[name] ?? \"\";\n  field(\"published\").checked = record.published;\n  document.querySelector(\"#editor-title\").textContent = \"Edit achievement\";\n  document.querySelector(\"#cancel-edit\").hidden = false;\n  if (record.file) {\n    const link = document.querySelector(\"#existing-file-link\");\n    link.href = record.file.url; link.textContent = record.file.name + \" ↗\";\n    document.querySelector(\"#existing-file\").hidden = false;\n  }\n  field(\"title\").focus();\n}\nfunction renderCollection() {\n  list.replaceChildren();\n  document.querySelector(\"#achievement-count\").textContent = String(achievements.length);\n  if (!achievements.length) { list.append(element(\"p\", \"collection-empty\", \"Your collection is empty. Add your first achievement when you’re ready.\")); return; }\n  for (const record of achievements) {\n    const article = element(\"article\", \"achievement-item\");\n    const meta = element(\"div\", \"item-meta\");\n    meta.append(element(\"span\", \"\", record.year + \" · \" + record.category), element(\"span\", \"item-status\" + (record.published ? \"\" : \" draft\"), record.published ? \"Published\" : \"Draft\"));\n    article.append(meta, element(\"h3\", \"\", record.title));\n    if (record.organizer) article.append(element(\"p\", \"item-description\", record.organizer));\n    if (record.description) article.append(element(\"p\", \"item-description\", record.description));\n    if (record.file) { const link = element(\"a\", \"item-attachment\", record.file.name + \" ↗\"); link.href = record.file.url; link.target = \"_blank\"; link.rel = \"noopener noreferrer\"; article.append(link); }\n    const actions = element(\"div\", \"item-actions\");\n    const editButton = element(\"button\", \"text-button\", \"Edit\"); editButton.type = \"button\"; editButton.setAttribute(\"aria-label\", \"Edit \" + record.title); editButton.addEventListener(\"click\", () => edit(record));\n    const deleteButton = element(\"button\", \"text-button delete-button\", \"Delete\"); deleteButton.type = \"button\"; deleteButton.setAttribute(\"aria-label\", \"Delete \" + record.title); deleteButton.addEventListener(\"click\", () => {\n      pendingDelete = record;\n      document.querySelector(\"#delete-description\").textContent = record.title;\n      document.querySelector(\"#delete-status\").textContent = \"\";\n      deleteDialog.showModal();\n    });\n    actions.append(editButton, deleteButton); article.append(actions); list.append(article);\n  }\n}\nasync function load() { const data = await api(\"/api/admin/achievements\"); achievements = data.achievements; renderCollection(); }\nform.addEventListener(\"submit\", async event => {\n  event.preventDefault();\n  if (!form.reportValidity()) return;\n  const id = field(\"id\").value;\n  saveButton.disabled = true;\n  status(formStatus, \"Saving…\"); status(pageStatus, \"\");\n  try {\n    const { achievement } = await api(\"/api/admin/achievements\" + (id ? \"/\" + id : \"\"), { method: id ? \"PUT\" : \"POST\", body: new FormData(form) });\n    resetEditor();\n    achievements = achievements.filter(record => record.id !== achievement.id).concat(achievement).sort((a, b) => b.year - a.year || b.createdAt.localeCompare(a.createdAt));\n    renderCollection();\n    status(pageStatus, achievement.published ? \"Achievement published on your portfolio.\" : \"Draft saved. It is only visible to you.\");\n  } catch (error) { status(formStatus, error.message, true); }\n  finally { saveButton.disabled = false; }\n});\ndocument.querySelector(\"#cancel-edit\").addEventListener(\"click\", resetEditor);\nfield(\"file\").addEventListener(\"change\", () => {\n  const file = field(\"file\").files[0];\n  const tooLarge = file?.size > 10 * 1024 * 1024;\n  field(\"file\").setCustomValidity(tooLarge ? \"Choose a file smaller than 10 MB.\" : \"\");\n  document.querySelector(\"#selected-file\").textContent = file ? file.name + \" · \" + (file.size / 1024 / 1024).toFixed(2) + \" MB\" : \"\";\n  if (tooLarge) field(\"file\").reportValidity();\n});\ndocument.querySelector(\"#confirm-delete\").addEventListener(\"click\", async () => {\n  if (!pendingDelete) return;\n  const button = document.querySelector(\"#confirm-delete\"); button.disabled = true;\n  try {\n    await api(\"/api/admin/achievements/\" + pendingDelete.id, { method: \"DELETE\" });\n    if (field(\"id\").value === pendingDelete.id) resetEditor();\n    achievements = achievements.filter(record => record.id !== pendingDelete.id);\n    renderCollection(); deleteDialog.close(); pendingDelete = null; status(pageStatus, \"Achievement deleted.\");\n  } catch (error) { document.querySelector(\"#delete-status\").textContent = error.message; }\n  finally { button.disabled = false; }\n});\nPromise.all([load(), api(\"/api/session\").then(session => { document.querySelector(\"#local-notice\").hidden = !session.localPreview; })])\n  .catch(error => { status(pageStatus, error.message, true); list.replaceChildren(element(\"p\", \"collection-empty\", \"Achievements could not be loaded. Reload this page to try again.\")); });\n","type":"text/javascript; charset=utf-8"}};


const RECORD_PREFIX = "achievements/records/";
const FILE_PREFIX = "achievements/files/";
const MAX_FILE_BYTES = 10 * 1024 * 1024;
const MAX_REQUEST_BYTES = MAX_FILE_BYTES + 64 * 1024;
const CATEGORIES = new Set(["Award", "Olympiad", "Competition", "Certificate", "Other"]);

class HttpError extends Error {
  constructor(status, message) { super(message); this.status = status; }
}

function response(body, status = 200, type = "application/json; charset=utf-8", extra = {}) {
  return new Response(body, { status, headers: {
    "Content-Type": type, "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "strict-origin-when-cross-origin", ...extra
  }});
}
function json(value, status = 200) { return response(JSON.stringify(value), status); }
function escapeHTML(value) {
  return String(value ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function isAdmin(request, env) {
  const userId = request.headers.get("oai-authenticated-user-id");
  const email = request.headers.get("oai-authenticated-user-email")?.trim().toLowerCase();
  // Sites supplies these verified headers. A browser-provided password is never used.
  return Boolean(userId && email && env.PORTFOLIO_ADMIN_EMAIL && email === env.PORTFOLIO_ADMIN_EMAIL.trim().toLowerCase());
}
function requireAdmin(request, env) {
  if (!isAdmin(request, env)) throw new HttpError(request.headers.get("oai-authenticated-user-id") ? 403 : 401, "Sign in with the portfolio owner's account to manage achievements.");
}
function requireSameOrigin(request) {
  if (request.headers.get("origin") !== new URL(request.url).origin || request.headers.get("x-portfolio-request") !== "1") {
    throw new HttpError(403, "This request must come from the portfolio admin page.");
  }
}
function bucket(env) {
  if (!env.BUCKET) throw new HttpError(503, "Achievement storage is not configured yet.");
  return env.BUCKET;
}
async function readRecord(env, id) {
  const object = await bucket(env).get(RECORD_PREFIX + id + ".json");
  return object ? object.json() : null;
}
async function readRecords(env) {
  const records = [];
  let cursor;
  do {
    const page = await bucket(env).list({ prefix: RECORD_PREFIX, limit: 250, ...(cursor ? { cursor } : {}) });
    const items = await Promise.all(page.objects.map(async object => {
      const data = await bucket(env).get(object.key);
      return data ? data.json() : null;
    }));
    records.push(...items.filter(Boolean));
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
  return records.sort((a, b) => b.year - a.year || b.createdAt.localeCompare(a.createdAt));
}
function publicRecord(record) {
  const { id, title, year, category, organizer, description, proofUrl, published, createdAt, updatedAt } = record;
  return { id, title, year, category, organizer, description, proofUrl, published, createdAt, updatedAt,
    file: record.file ? { name: record.file.name, type: record.file.type, size: record.file.size, url: "/files/" + id } : null
  };
}
function renderAchievements(records) {
  if (!records.length) return '<p class="empty-note">Achievements and certificates will be added here.</p>';
  return '<ol class="milestone-list">' + records.map(record => {
    const file = record.file ? `<a class="achievement-file" href="/files/${record.id}" target="_blank" rel="noopener noreferrer">${record.file.type === "application/pdf" ? "Download certificate (PDF)" : "View certificate"} <span aria-hidden="true">↗</span></a>` : "";
    const proof = record.proofUrl ? `<a class="achievement-file" href="${escapeHTML(record.proofUrl)}" target="_blank" rel="noopener noreferrer">View source <span aria-hidden="true">↗</span></a>` : "";
    return `<li><span class="timeline-year">${record.year}</span><div><h3>${escapeHTML(record.title)}</h3><span class="entry-note">${escapeHTML(record.category)}${record.organizer ? " · " + escapeHTML(record.organizer) : ""}</span>${record.description ? `<p class="achievement-description">${escapeHTML(record.description)}</p>` : ""}<div class="achievement-files">${file}${proof}</div></div></li>`;
  }).join("") + "</ol>";
}
async function limitedForm(request) {
  const contentType = request.headers.get("content-type") || "";
  if (!contentType.startsWith("multipart/form-data;")) throw new HttpError(415, "Please use the achievement form.");
  if (Number(request.headers.get("content-length")) > MAX_REQUEST_BYTES) throw new HttpError(413, "Choose a file smaller than 10 MB.");
  if (!request.body) throw new HttpError(400, "The form is empty.");
  const reader = request.body.getReader();
  const chunks = [];
  let length = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    length += value.byteLength;
    if (length > MAX_REQUEST_BYTES) { await reader.cancel(); throw new HttpError(413, "Choose a file smaller than 10 MB."); }
    chunks.push(value);
  }
  const bytes = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
  try { return await new Response(bytes, { headers: { "content-type": contentType } }).formData(); }
  catch { throw new HttpError(400, "The uploaded form could not be read. Please try again."); }
}
function textField(form, name, max, required = false) {
  const value = form.get(name) ?? "";
  if (typeof value !== "string") throw new HttpError(400, "Invalid " + name + ".");
  const text = value.trim();
  if ((required && !text) || text.length > max) throw new HttpError(400, "Please check the " + name + " field.");
  return text;
}
function validateFields(form) {
  const title = textField(form, "title", 160, true);
  const rawYear = textField(form, "year", 4, true);
  const year = Number(rawYear);
  if (!/^\d{4}$/.test(rawYear) || year < 1900 || year > 2100) throw new HttpError(400, "Enter a valid four-digit year.");
  const category = textField(form, "category", 30, true);
  if (!CATEGORIES.has(category)) throw new HttpError(400, "Choose an achievement category.");
  const organizer = textField(form, "organizer", 160);
  const description = textField(form, "description", 1500);
  let proofUrl = textField(form, "proofUrl", 1500);
  if (proofUrl) {
    try {
      const url = new URL(proofUrl);
      if (!/^https?:$/.test(url.protocol) || url.username || url.password) throw new Error();
      proofUrl = url.href;
    } catch { throw new HttpError(400, "The source link must start with https:// or http://."); }
  }
  return { title, year, category, organizer, description, proofUrl, published: form.get("published") === "on" };
}
async function validateFile(file) {
  if (file.size > MAX_FILE_BYTES) throw new HttpError(413, "Choose a file smaller than 10 MB.");
  const bytes = new Uint8Array(await file.arrayBuffer());
  let type;
  let extension;
  const start = new TextDecoder().decode(bytes.slice(0, 12));
  if (start.startsWith("%PDF-")) { type = "application/pdf"; extension = ".pdf"; }
  else if ([137,80,78,71,13,10,26,10].every((value, index) => bytes[index] === value)) { type = "image/png"; extension = ".png"; }
  else if (bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255) { type = "image/jpeg"; extension = ".jpg"; }
  else if (start.startsWith("RIFF") && start.slice(8, 12) === "WEBP") { type = "image/webp"; extension = ".webp"; }
  else throw new HttpError(415, "Upload a PDF, JPG, PNG, or WebP file.");
  const name = (file.name.replace(/[\x00-\x1f\x7f/\\]/g, "_").replace(/\.[^.]*$/, "").slice(0, 140) || "certificate") + extension;
  return { bytes, type, name, size: file.size };
}
async function saveAchievement(request, env, id) {
  const existing = id ? await readRecord(env, id) : null;
  if (id && !existing) throw new HttpError(404, "This achievement no longer exists.");
  const form = await limitedForm(request);
  const fields = validateFields(form);
  if (existing && textField(form, "updatedAt", 50, true) !== existing.updatedAt) throw new HttpError(409, "This achievement changed in another tab. Reload it before saving.");
  const recordId = id || crypto.randomUUID();
  const now = new Date().toISOString();
  const record = { ...fields, id: recordId, createdAt: existing?.createdAt || now, updatedAt: now, file: existing?.file || null };
  const upload = form.get("file");
  let newKey;
  if (upload && typeof upload !== "string" && upload.size > 0) {
    const file = await validateFile(upload);
    newKey = FILE_PREFIX + recordId + "/" + crypto.randomUUID();
    await bucket(env).put(newKey, file.bytes, { httpMetadata: { contentType: file.type } });
    record.file = { key: newKey, name: file.name, type: file.type, size: file.size };
  } else if (form.get("removeFile") === "on") record.file = null;
  try { await bucket(env).put(RECORD_PREFIX + recordId + ".json", JSON.stringify(record), { httpMetadata: { contentType: "application/json" } }); }
  catch (error) { if (newKey) await bucket(env).delete(newKey); throw error; }
  if (existing?.file && existing.file.key !== record.file?.key) {
    // The saved record already references the new file. An old orphan must not undo the save.
    try { await bucket(env).delete(existing.file.key); } catch { console.warn("Old attachment cleanup failed."); }
  }
  return json({ achievement: publicRecord(record) }, id ? 200 : 201);
}
async function serveFile(request, env, id) {
  const record = await readRecord(env, id);
  if (!record?.file || (!record.published && !isAdmin(request, env))) throw new HttpError(404, "File not found.");
  const object = await bucket(env).get(record.file.key);
  if (!object) throw new HttpError(404, "File not found.");
  const encoded = encodeURIComponent(record.file.name).replace(/['()*]/g, char => "%" + char.charCodeAt(0).toString(16));
  return response(object.body, 200, record.file.type, {
    "Content-Disposition": (record.file.type === "application/pdf" ? "attachment" : "inline") + "; filename*=UTF-8''" + encoded,
    "Content-Security-Policy": "default-src 'none'; sandbox"
  });
}
function htmlResponse(html, status = 200) {
  return response(html, status, "text/html; charset=utf-8", {
    "Content-Security-Policy": "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data: blob:; connect-src 'self'; base-uri 'self'; form-action 'self'; object-src 'none'"
  });
}

const app = {
  async fetch(request, env) {
    if (request.method === "HEAD") {
      const result = await app.fetch(new Request(request.url, { headers: request.headers, method: "GET" }), env);
      return new Response(null, { status: result.status, headers: result.headers });
    }
    try {
      const url = new URL(request.url);
      const path = url.pathname;
      const method = request.method;
      if (path === "/api/session" && method === "GET") return json({ isAdmin: isAdmin(request, env), localPreview: env.LOCAL_PREVIEW === "1" });
      if (path === "/api/achievements" && method === "GET") return json({ achievements: (await readRecords(env)).filter(record => record.published).map(publicRecord) });
      const adminRoute = path.match(/^\/api\/admin\/achievements(?:\/([a-f0-9-]{36}))?$/);
      if (adminRoute) {
        requireAdmin(request, env);
        const id = adminRoute[1];
        if (method === "GET" && !id) return json({ achievements: (await readRecords(env)).map(publicRecord) });
        requireSameOrigin(request);
        if (method === "POST" && !id) return await saveAchievement(request, env);
        if (method === "PUT" && id) return await saveAchievement(request, env, id);
        if (method === "DELETE" && id) {
          const record = await readRecord(env, id);
          if (!record) throw new HttpError(404, "This achievement no longer exists.");
          await bucket(env).delete([RECORD_PREFIX + id + ".json", ...(record.file ? [record.file.key] : [])]);
          return json({ deleted: true });
        }
        throw new HttpError(405, "Method not allowed.");
      }
      const fileRoute = path.match(/^\/files\/([a-f0-9-]{36})$/);
      if (fileRoute && method === "GET") return await serveFile(request, env, fileRoute[1]);
      if ((path === "/admin" || path === "/admin/") && method === "GET") {
        if (!request.headers.get("oai-authenticated-user-id")) return Response.redirect(url.origin + "/signin-with-chatgpt?return_to=%2Fadmin", 302);
        requireAdmin(request, env);
        return htmlResponse(ASSETS["/admin"].body);
      }
      if ((path === "/" || path === "/index.html") && method === "GET") {
        let achievements;
        try { achievements = renderAchievements((await readRecords(env)).filter(record => record.published)); }
        catch { achievements = '<p class="empty-note">Achievements are temporarily unavailable. Please check back later.</p>'; }
        return htmlResponse(ASSETS["/"].body.replace(/<!-- ACHIEVEMENTS_START -->[\s\S]*?<!-- ACHIEVEMENTS_END -->/, achievements));
      }
      const asset = ASSETS[path];
      if (asset && path !== "/admin" && method === "GET") return response(asset.body, 200, asset.type);
      if (path.startsWith("/api/") || path.startsWith("/files/")) throw new HttpError(404, "Not found.");
      return htmlResponse('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Page not found</title><link rel="stylesheet" href="/styles.css"><main class="container hero"><h1>Page not found.</h1><p><a href="/">Return to Anton’s portfolio →</a></p></main></html>', 404);
    } catch (error) {
      if (!(error instanceof HttpError)) console.error("Portfolio request failed.");
      return json({ error: error instanceof HttpError ? error.message : "Something went wrong. Please try again." }, error.status || 500);
    }
  }
};
export default app;
